import { Card, CardContent } from "@/registry/erbium/ui/card";
import {
  Carousel,
  CarouselNext,
  CarouselPrevious,
  CarouselSlide,
  CarouselSlides,
} from "@/registry/erbium/ui/carousel";

export default function CarouselExample() {
  return (
    <Carousel aria-label="Numbers" className="w-full max-w-xs">
      <CarouselSlides>
        {Array.from({ length: 5 }, (_, index) => (
          <CarouselSlide key={index}>
            <Card className="aspect-square">
              <CardContent className="flex min-h-0 flex-1 items-center justify-center">
                <span className="text-display font-semibold">{index + 1}</span>
              </CardContent>
            </Card>
          </CarouselSlide>
        ))}
      </CarouselSlides>
      <CarouselPrevious />
      <CarouselNext />
    </Carousel>
  );
}

import CarouselExample from "../examples/carousel-demo";

const Example = () => (
  <div className="w-full max-w-2xl min-w-72 p-4">
    <CarouselExample />
  </div>
);

export default Example;
